			'm7♭5': [0, 3, 6, 10],
			'-7(b5)': [0, 3, 6, 10],
			'-7b5': [0, 3, 6, 10],

			'7b5': [0, 4, 6, 10],
			'7(b5)': [0, 4, 6, 10],
			'7♭5': [0, 4, 6, 10],

