			'7b9,b5': [0, 4, 6, 10, 13],
			'7(#9,b5)': [0, 4, 6, 10, 15],
			'7#9b5': [0, 4, 6, 10, 15],
			'maj7(b5)': [0, 4, 6, 11],
			'maj7b5': [0, 4, 6, 11],
			'13(b5)': [0, 4, 6, 10, 14, 21],
			'13b5': [0, 4, 6, 10, 14, 21],

