			'11': [0, 7, 10, 14, 17],
			'13': [0, 4, 7, 10, 14, 21],
			'7b9': [0, 4, 7, 10, 13],
			'7♭9': [0, 4, 7, 10, 13],
			'7(b9)': [0, 4, 7, 10, 13],
			'7(#9)': [0, 4, 7, 10, 15],
			'7#9': [0, 4, 7, 10, 15],
